installs.check:
su -s /bin/bash linuxbrew -c '[ -d "$PWD" ] && [ -r "$PWD" ] || cd /home/linuxbrew
export HOMEBREW_NO_AUTO_UPDATE=1 HOMEBREW_NO_ANALYTICS=1 HOMEBREW_NO_ENV_HINTS=1 NONINTERACTIVE=1 HOMEBREW_CURL_RETRIES=1
set -uo pipefail
deps=$(/home/linuxbrew/.linuxbrew/bin/brew deps --for-each '\''gh'\'' '\''pipx'\'' '\''go'\'')
shared=$(printf '\''%s\n'\'' "$deps" | sed '\''s/^[^:]*: *//'\'' | tr '\'' '\'' '\''\n'\'' | grep -vx -e '\'''\'' -e glibc -e gcc | sort | uniq -d || true)
if [ -z "$shared" ]; then exit 0; fi
have=$(/home/linuxbrew/.linuxbrew/bin/brew list --versions $shared 2>&1) && exit 0
case "$have" in *Error:*) printf '\''%s\n'\'' "$have" | grep Error: | tail -1; exit 1 ;; esac
printf '\''%s\n'\'' "$deps" | shared="$shared" have="$have" awk '\''{ f = $1; sub(/:$/, "", f); for (i = 2; i <= NF; i++) if ($i in users) users[$i] = users[$i] SUBSEP f; else users[$i] = f }
END {
  m = split(ENVIRON["have"], h, "\n"); for (i = 1; i <= m; i++) { split(h[i], w, " "); got[w[1]] = 1 }
  n = split(ENVIRON["shared"], s, /[ \n]+/); k = 0
  for (i = 1; i <= n; i++) { b = s[i]; sub(/.*\//, "", b); if (s[i] != "" && !(b in got)) gone[++k] = s[i] }
  out = ""
  for (i = 1; i <= k && i <= 3; i++) {
    if (ENVIRON["names"] != "") { out = out (i == 1 ? "" : (i == k ? " and " : ", ")) gone[i]; continue }
    u = split(users[gone[i]], who, SUBSEP); list = ""
    for (j = 1; j <= u; j++) list = list (j == 1 ? "" : (j == u ? " and " : ", ")) who[j]
    out = out (i == 1 ? "" : " ") gone[i] " is not installed; " list (u == 1 ? " needs" : " need") " it."
  }
  if (k > 3) out = out (ENVIRON["names"] != "" ? " and " (k - 3) " more" : " " (k - 3) (k == 4 ? " more shared dependency is" : " more shared dependencies are") " not installed.")
  if (k > 0) print out
}'\''
exit 1'

